INIT="window.SERR=[]; addEventListener('error',e=>SERR.push(String(e.message))); window.SKIP_DAWN=1; try{localStorage.setItem('cbs.base.settings', JSON.stringify({playAs:'partner', nights:'gentle'}))}catch(e){}" CLEAR=1 SW=300 timeout 1500 python3 st.py \
"(async()=>{ document.getElementById('title').classList.add('hide'); G.jumpTo('night'); await T.run(60,[1],{until:'G.S.chapter===\"night\" && G.NIGHT.swapped && !G.busy()'}); await T.walk(6.5,1.2,25); await T.walk(11.5,0.6,25); await T.walk(13.0,-0.9,15); G.INTER.find(i=>i.id==='hWater').act(); await T.run(8); await T.run(90,[1,2,1],{until:'G.NIGHT.canWhistle && !G.busy()'}); let came=false; for(let k=0;k<70;k++){ await T.run(1); if(G.NIGHT.searching) came=true; } G.INTER.find(i=>i.id==='eWhistle').act(); const r=await T.run(40,[1],{until:'G.NIGHT.outside'}); return [G.gentle(), came, r.ch, G.NIGHT.outside, G.S.vars.caught, SERR] })()"
